+// API keys and roles. Keys live in the data as `apiKeys` ({ key, name,
+// role }); a role may do everything the roles below it may do.
+import { createHash, timingSafeEqual } from "node:crypto";
+import { AppError } from "../errors.js";
+
+/** Roles from least to most allowed. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+const digest = (text) => createHash("sha256").update(String(text)).digest();
+
+/** The API key record for an `Authorization: Bearer <key>` header value; throws `unauthorized`. */
+export function authenticate(store, authorization) {
+  const m = /^Bearer +(\S+)$/i.exec(typeof authorization === "string" ? authorization.trim() : "");
+  if (!m) throw new AppError("unauthorized");
+  const given = digest(m[1]);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key === "string" && k.key !== "" && timingSafeEqual(digest(k.key), given)) found = k;
+  }
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Whether `role` may do what needs `needed` (unknown roles may do nothing). */
+export function allows(role, needed) {
+  const have = ROLES.indexOf(role);
+  const need = ROLES.indexOf(needed);
+  return have !== -1 && need !== -1 && have >= need;
+}
+
+/** Throws `forbidden` unless the key's role may do what needs `needed`. */
+export function authorize(apiKey, needed) {
+  if (!allows(apiKey.role, needed)) throw new AppError("forbidden", { role: apiKey.role });
+}
